window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/humanas_2021.js"]=[{"title":"O expediente invade o tempo privado","steps":["O turno terminou, mas mensagens mantêm o vínculo laboral.","O celular devolve o trabalhador às demandas da empresa durante o jantar.","B identifica atividades extras, além do horário regular."],"alternatives":{"A":"A vida privada é invadida, não protegida.","B":"O trabalho se estende ao tempo que seria da família.","C":"Não se descrevem novas etapas de burocracia.","D":"As mensagens são profissionais, não lazer diversificado.","E":"Os afazeres domésticos não deixam de existir por causa do celular."},"takeaway":"Conectividade não implica disponibilidade profissional ilimitada.","key":"humanas:H762","area":"humanas","year":2021,"number":46,"answer":"B","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Herança e mérito não são a mesma origem da riqueza","steps":["O retorno do capital cresce mais que renda e produção.","A riqueza herdada pode superar o patrimônio obtido pelo trabalho de uma vida.","A enfraquece a explicação das posições sociais apenas pelo mérito."],"alternatives":{"A":"A vantagem herdada contraria a ideia de sucesso proporcional ao esforço individual.","B":"O mecanismo fortalece vantagens de nascimento, não as enfraquece.","C":"O texto não avalia o cumprimento de uma lei específica.","D":"Os rendimentos do capital podem crescer no cenário descrito.","E":"A questão é a legitimidade meritocrática, não demonstrar eficiência de mercados."},"takeaway":"Desigualdade de condições iniciais dificulta atribuir resultados só ao esforço.","key":"humanas:H763","area":"humanas","year":2021,"number":47,"answer":"A","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Melhoramento adapta variedades a ambientes distintos","steps":["O programa atende semiárido, regiões tropicais e Serra Gaúcha.","Seleção e manejo precisam responder a condições diferentes de clima e cultivo.","D identifica os elementos ambientais singulares das regiões."],"alternatives":{"A":"O objetivo não é conservar espécies nativas ameaçadas.","B":"Não se afirma autonomia econômica completa das cadeias.","C":"Não se pretende manter uma estrutura fundiária particular.","D":"Ambientes diferentes exigem variedades e manejos adequados.","E":"O texto inclui exportação, não apenas consumo interno."},"takeaway":"Tecnologia agrícola pode ajustar plantas e manejo às condições regionais.","key":"humanas:H310","area":"humanas","year":2021,"number":48,"answer":"D","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Preservar não significa necessariamente congelar o monumento","steps":["O primeiro texto defende transmissão autêntica do patrimônio.","O segundo critica proteção que ignora contexto social e favorece abandono.","C localiza a divergência nas políticas de conservação."],"alternatives":{"A":"Nenhum dos textos propõe comércio de imagens religiosas.","B":"Não se discute prioritariamente trocar materiais das obras.","C":"São concepções diferentes de como conservar bens culturais.","D":"Não há defesa de privatização de sítios arqueológicos.","E":"O debate envolve monumentos e contexto urbano, não só peças de museu."},"takeaway":"Compare os meios de preservar, não apenas o objetivo comum de preservação.","key":"humanas:H793","area":"humanas","year":2021,"number":49,"answer":"C","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O custo ambiental também é distribuído internacionalmente","steps":["Resíduos gerados em circuitos de consumo são enviados ao Gana.","A desmontagem perigosa é transferida a trabalhadores com menor proteção.","B reconhece a divisão internacional do trabalho e dos riscos."],"alternatives":{"A":"Intoxicação e desproteção contradizem cidadania plenamente exercida.","B":"Etapas de baixo valor e alto risco são deslocadas entre países desigualmente inseridos.","C":"Toyotismo não explica diretamente o fluxo internacional do lixo.","D":"Queimar resíduos sem controle não constitui economia sustentável.","E":"O fluxo descrito explora exportações, não barreiras protecionistas."},"takeaway":"Cadeias globais distribuem produtos, rendimentos e danos de maneira desigual.","key":"humanas:H364","area":"humanas","year":2021,"number":50,"answer":"B","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Equidade atende necessidades diferentes sem esgotar a água","steps":["O texto inclui indústria, irrigação e agricultura de subsistência.","Preços e autorizações devem considerar suas peculiaridades e sustentabilidade.","A traduz distribuição equitativa do acesso, não cotas idênticas para todos."],"alternatives":{"A":"Equidade combina necessidades distintas com conservação da disponibilidade.","B":"O alcance inclui usos rurais e industriais, não só rede urbana.","C":"Não se propõe simplesmente reduzir a vazão dos rios.","D":"Recuperação de solos não é a política hídrica enunciada.","E":"Reciclagem de produtos não é o objeto central da proposta."},"takeaway":"Distribuição equitativa não exige que usuários com necessidades diferentes recebam volumes iguais.","key":"humanas:H582","area":"humanas","year":2021,"number":51,"answer":"A","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A pressão britânica busca impedir retomada do tráfico","steps":["A Lei Aberdeen permitia repressão britânica ao tráfico atlântico.","O governo teme revogá-la sem instrumento substituto eficaz.","D identifica manter a proibição comercial de pessoas escravizadas."],"alternatives":{"A":"A preocupação é impedir o tráfico, não conciliar jurisdições como fim principal.","B":"Não se busca compartilhar o comércio de pessoas escravizadas.","C":"Higienismo não é a política debatida no episódio.","D":"O receio de retorno aos velhos hábitos explica preservar a proibição do tráfico.","E":"Não há promoção de atividade familiar no conflito diplomático."},"takeaway":"Diferencie proibir tráfico internacional de abolir a escravidão interna.","key":"humanas:H040","area":"humanas","year":2021,"number":52,"answer":"D","subject":"História do Brasil","topic":"Escravidão, abolição e resistências","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A crença faz parte da memória cultural","steps":["O narrador recorda pratos virados e a oração da avó.","A prática associa experiência climática, crença e transmissão entre gerações.","B reconhece patrimônio cultural, sem comprovar previsão ou controle científico da chuva."],"alternatives":{"A":"O apelido ligado a viúvas não faz do casamento o núcleo da lembrança.","B":"O costume místico integra vivências e memória da região.","C":"A comparação com Chicó não transforma a narrativa em teatro político.","D":"Não se relata produção cinematográfica sobre desastres.","E":"A prática não é uma argumentação literária sobre catástrofes."},"takeaway":"Valor cultural e eficácia física de um ritual são questões diferentes.","key":"humanas:H794","area":"humanas","year":2021,"number":53,"answer":"B","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Modernização técnica pode precarizar relações sociais","steps":["A reorganização envolve controle, qualificação e contratação.","O texto destaca terceirização, precarização e flexibilização.","C explica a crítica à fragilização das relações trabalhistas."],"alternatives":{"A":"Executar tarefas é genérico e não exprime a crítica social.","B":"Formação de profissionais liberais não é o efeito central.","C":"A flexibilidade descrita pode reduzir estabilidade e proteção do trabalho.","D":"A hierarquia de executivos não é o foco do trecho.","E":"Conhecimento científico não é criticado por si, mas seu uso nas relações produtivas."},"takeaway":"Não reduza mudança tecnológica a máquinas: observe contratos e poder.","key":"humanas:H764","area":"humanas","year":2021,"number":54,"answer":"C","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A provisoriedade envolve pertencimento e proteção jurídica","steps":["Refugiados mantêm vínculos com a origem sem integrar plenamente o destino.","O estatuto jurídico também muda e pode gerar insegurança.","E reúne desenraizamento cultural e insegurança legal, sem dizer que refugiados não têm direitos."],"alternatives":{"A":"Não se descreve ascensão social como causa geral.","B":"Miscigenação não explica o problema identitário apresentado.","C":"A qualificação profissional e a polícia não são os eixos do trecho.","D":"Crises financeiras podem motivar migrações, mas não resumem a condição analisada.","E":"Pertencimento incompleto e transição de estatuto jurídico explicam a provisoriedade."},"takeaway":"Refúgio é uma condição com proteção jurídica, não sinônimo de ausência de direitos.","key":"humanas:H491","area":"humanas","year":2021,"number":55,"answer":"E","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A desigualdade de gênero atravessa a ciência","steps":["As mulheres acompanham maridos em expedições.","Sua participação não aparece organizada por projetos próprios em igualdade de condições.","D identifica reprodução de estratificações sociais no campo científico."],"alternatives":{"A":"A subordinação descrita não afirma igualdade de gênero.","B":"A questão é a posição social na ciência, não a diversificação do lazer.","C":"A lógica patriarcal permanece no condicionamento das trajetórias.","D":"O campo científico incorpora hierarquias de gênero presentes na sociedade.","E":"Não se afirma simples troca de tarefas domésticas por científicas."},"takeaway":"Participação feminina não é, por si, prova de igualdade de oportunidades e autonomia.","key":"humanas:H765","area":"humanas","year":2021,"number":56,"answer":"D","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O consumo participa da construção da identidade","steps":["Marcuse descreve necessidades sociais interiorizadas como individuais.","As pessoas reconhecem sua própria imagem nos bens que possuem.","D aponta mecanismos subjetivos de identificação com mercadorias."],"alternatives":{"A":"O trecho não atribui o mecanismo apenas à divulgação estatal.","B":"Incentivos econômicos isolados não explicam reconhecer a própria alma nos objetos.","C":"Não se trata de uma regra explícita de organização coletiva.","D":"A mercadoria passa a mediar a percepção que a pessoa tem de si.","E":"O consumo pode alimentar identificação narcísica, não simplesmente reprimi-la."},"takeaway":"Pergunte quando possuir um objeto se transforma em definir quem se é.","key":"humanas:H704","area":"humanas","year":2021,"number":57,"answer":"D","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Transformar a paisagem também muda referências sociais","steps":["Obras substituem praças, árvores e lugares de encontro.","O espaço urbano é tratado como mercadoria e muda rapidamente.","E identifica alteração da organização da paisagem geográfica."],"alternatives":{"A":"O relato enfatiza perda e transformação dos modos de convívio.","B":"Os usos públicos são substituídos, não preservados em sua essência.","C":"Não se apresenta ampliação da proteção ambiental.","D":"Regras de participação política não são a causa explicitada.","E":"Mudanças materiais reorganizam usos, encontros e referências dos habitantes."},"takeaway":"Paisagem urbana envolve materialidade e relações sociais em transformação.","key":"humanas:H196","area":"humanas","year":2021,"number":58,"answer":"E","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O conhecimento é construído pela observação vivida","steps":["Os sertanejos observam astros e nuvens ao longo de gerações.","As interpretações resultam de experiência sensorial e transmissão cultural.","B caracteriza experiência perceptiva, sem validar cientificamente cada previsão citada."],"alternatives":{"A":"Não se descreve teste controlado de uma técnica científica.","B":"O saber decorre do contato e observação recorrente do ambiente.","C":"As tradições são mobilizadas, não negadas.","D":"O trecho valoriza um saber situado, não padronização de todas as culturas.","E":"Não se afirma uma informação uniforme e universalmente validada."},"takeaway":"Reconhecer um modo de produzir conhecimento não exige equipará-lo à previsão meteorológica testada.","key":"humanas:H451","area":"humanas","year":2021,"number":59,"answer":"B","subject":"Geografia","topic":"Climatologia e biomas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A imagem do gado critica submissão coletiva","steps":["A massa caminha e dá mais do que recebe.","Povo marcado e povo feliz criam contraste irônico.","B identifica passividade diante de uma condição de exploração."],"alternatives":{"A":"Militância sugere ação organizada, diferente da submissão criticada.","B":"A felicidade enunciada ironicamente contrasta com aceitar receber menos.","C":"Não há prática religiosa de caridade como tema central.","D":"Autocontrole individual não explica a relação coletiva desigual.","E":"O trecho não descreve contestação eleitoral do grupo."},"takeaway":"A ironia pode dizer felicidade para denunciar conformismo e desigualdade.","key":"humanas:H821","area":"humanas","year":2021,"number":60,"answer":"B","subject":"Sociologia","topic":"Poder, Estado e política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A reforma urbana busca disputar circuitos globais","steps":["O projeto associa torres, consumo e serviços internacionais.","As referências são waterfronts de outras cidades conectadas globalmente.","A aponta competitividade global, não garantia de inclusão habitacional."],"alternatives":{"A":"A remodelação busca inserir a área no mercado e na disputa entre cidades.","B":"A valorização imobiliária pode ser estimulada, não contida.","C":"A meta descrita não garante acesso popular às novas moradias.","D":"Substituir a paisagem anterior não prioriza funções tradicionais.","E":"Participação popular não é o princípio enfatizado pela descrição do projeto."},"takeaway":"Revitalização é uma palavra de projeto: examine beneficiários e interesses antes de presumir inclusão.","key":"humanas:H397","area":"humanas","year":2021,"number":61,"answer":"A","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Baixa inovação limita autonomia produtiva","steps":["A indústria participa pouco das novas tecnologias.","O crescimento depende de commodities e setores de baixa inovação futura.","D identifica subordinação aos fluxos globais, sem dizer que o país deixe de produzir."],"alternatives":{"A":"Não há demonstração de redução do preço dos alimentos.","B":"O trecho não descreve retorno da propriedade estatal das empresas.","C":"Não se demonstra ampliação sustentada de renda e consumo.","D":"Dependência tecnológica e especialização limitam a posição nos circuitos internacionais.","E":"Incentivar modernização seria uma resposta possível, não o efeito já descrito."},"takeaway":"Diferencie diagnóstico de dependência das políticas que poderiam enfrentá-la.","key":"humanas:H424","area":"humanas","year":2021,"number":62,"answer":"D","subject":"Geografia","topic":"Industrialização, trabalho e redes","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Território também é vínculo social e identidade","steps":["A mineração interfere em práticas de diferentes comunidades.","Compensação financeira nem sempre recompõe relações desfeitas.","B reconhece rompimento de vínculos locais e dinâmicas territoriais."],"alternatives":{"A":"O dano ultrapassa falta de patrocínio cultural.","B":"A instalação abrupta rompe usos do espaço e relações coletivas.","C":"Receber investimento não garante recompor modos de vida.","D":"Não se descreve implantação de práticas agroecológicas.","E":"Os grupos não são apresentados como enriquecidos pelo processo."},"takeaway":"Uma indenização monetária não necessariamente repõe relações, memória e acesso ao território.","key":"humanas:H270","area":"humanas","year":2021,"number":63,"answer":"B","subject":"Geografia","topic":"Meio ambiente e problemas ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Minoria é posição de poder, não só quantidade","steps":["O texto recusa definir maioria apenas pelo tamanho numérico.","Um padrão dominante faz outros grupos ocuparem posição minoritária.","C remete à imposição arbitrária dessa relação social, não a uma hierarquia biológica natural."],"alternatives":{"A":"Um grupo pode ser minoritário politicamente sem estar em extinção.","B":"Incentivos estatais não são condição necessária da definição.","C":"A dominação institui padrões que subordinam outros grupos, sem fundamento natural obrigatório.","D":"A relação descrita é assimétrica, não de equivalência de poder.","E":"Diferenças biológicas não legitimam nem explicam naturalmente a dominação."},"takeaway":"Um grupo numericamente grande pode ser minorizado nas relações de poder.","key":"humanas:H705","area":"humanas","year":2021,"number":64,"answer":"C","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A oposição de interesses é uma relação de classe","steps":["Engels contrapõe interesses dos trabalhadores e da classe adversária.","As declarações de simpatia são confrontadas com ações incompatíveis.","A identifica luta de classes, não a análise técnica de uma mercadoria."],"alternatives":{"A":"A oposição entre posições e interesses sociais estrutura o argumento.","B":"A mais-valia exige analisar apropriação do trabalho excedente, não explicitada aqui.","C":"Não se discute desenho ou validação de um método científico.","D":"Indagação em geral não caracteriza o conflito social apresentado.","E":"Fetichismo trata da aparência das relações nas mercadorias, não é o eixo do trecho."},"takeaway":"Identifique o conceito pelo mecanismo descrito, não apenas pelo nome do autor.","key":"humanas:H766","area":"humanas","year":2021,"number":65,"answer":"A","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A política proposta deve enfrentar exclusões","steps":["Os dados mostram seletividade social, racial e educacional do encarceramento.","O comando pede diminuir a problemática, não ampliar a punição.","B prioriza inclusão social; isso não implica atribuir criminalidade natural a qualquer grupo."],"alternatives":{"A":"O Código Civil não é o instrumento central da política penal discutida.","B":"Educação, oportunidades e direitos enfrentam condições estruturais de exclusão.","C":"Punir adolescentes mais cedo não responde ao diagnóstico de inclusão.","D":"Corrupção é relevante, mas não o recorte evidenciado pelo perfil apresentado.","E":"Aumentar penas não promove a inclusão social pedida."},"takeaway":"Dados sobre grupos presos não permitem concluir propensão biológica ou moral ao crime.","key":"humanas:H737","area":"humanas","year":2021,"number":66,"answer":"B","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O incêndio reorganiza espaço e práticas","steps":["A destruição interrompe a vida urbana materialmente.","As medidas posteriores mudam topografia e costumes comunitários.","E reúne essas duas dimensões, sem supor substituição automática do governo."],"alternatives":{"A":"Prevenção e higiene não abrangem os efeitos que o fechamento destaca.","B":"Não se faz diagnóstico de degradação ambiental como eixo do relato.","C":"A leitura religiosa já existia; o texto enfatiza reorganização após a destruição.","D":"Não se demonstra necessariamente mudança do sistema político local.","E":"Reconstrução altera lugares ocupados e formas de convivência."},"takeaway":"Consequências de uma catástrofe podem ultrapassar perdas materiais e transformar relações sociais.","key":"humanas:H172","area":"humanas","year":2021,"number":67,"answer":"E","subject":"História Geral","topic":"Idade Média","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A comunicação amplia alianças","steps":["A carta e as hashtags tornam pública a demanda territorial.","Pessoas fora da comunidade aderem e difundem sua identidade e reivindicação.","E identifica apoio de segmentos externos, sem apagar a identidade indígena."],"alternatives":{"A":"O caso mostra fortalecimento da mobilização política.","B":"A afirmação pública do nome do povo não dissolve sua identidade.","C":"O objetivo imediato é apoio territorial, não vender no mercado global.","D":"A tecnologia serve a uma reivindicação ligada ao território de origem.","E":"A difusão alcança apoiadores de fora dos próprios grupos indígenas."},"takeaway":"Usar uma tecnologia contemporânea não torna um povo menos indígena.","key":"humanas:H846","area":"humanas","year":2021,"number":68,"answer":"E","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conhecer o território permite agir sobre ele","steps":["O governo cria instituições geográficas e estatísticas.","Dados regionais oferecem base para intervenção e planejamento estatal.","C identifica conhecimento científico das diversidades regionais."],"alternatives":{"A":"Preservação do sertão não é a finalidade específica atribuída ao conjunto.","B":"Não se demonstra controle direto da natalidade ou do crescimento populacional.","C":"Mapas e estatísticas ampliam a capacidade de conhecer e governar o território.","D":"A criação dos órgãos não equivale a bloquear migração rural-urbana.","E":"Não se apresenta uma proposta específica de novos estados."},"takeaway":"Produção de dados pode ser um instrumento de poder e de planejamento territorial.","key":"humanas:H106","area":"humanas","year":2021,"number":69,"answer":"C","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conhecimentos indígenas ajudam a recuperar o Cerrado","steps":["Os Xavante reconhecem condições de germinação das espécies.","O trabalho reúne esse saber e o de pesquisadores urbanos.","C vincula saber tradicional à conservação ambiental, sem recomendar fogo indiscriminado."],"alternatives":{"A":"O relato é de restauração ecológica, não logística agrícola nacional.","B":"Não se descreve fornecimento de hortaliças a cidades.","C":"Conhecer sementes e suas interações permite recuperar a vegetação.","D":"Não há programa de criação e melhoramento de gado.","E":"Recuperar diversidade nativa não se reduz a reflorestamento comercial."},"takeaway":"Conhecimento situado pode dialogar com pesquisa científica em projetos de conservação.","key":"humanas:H795","area":"humanas","year":2021,"number":70,"answer":"C","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Da rocha aos sedimentos e a novas rochas","steps":["O texto descreve desagregação, transporte e deposição.","Sedimentos acumulados podem sofrer compactação e cimentação.","A abrange essa sequência como ciclo sedimentar."],"alternatives":{"A":"O ciclo reúne produção, transporte e acumulação de sedimentos.","B":"Abalos sísmicos não são o transporte superficial narrado.","C":"Intemperismo biológico seria só um processo parcial e nem é especificado.","D":"Basalto se forma por resfriamento de lava, não pela sequência narrada.","E":"Compactação é só uma etapa posterior, não o conjunto do processo."},"takeaway":"Não escolha uma etapa isolada quando o comando pede o processo completo.","key":"humanas:H528","area":"humanas","year":2021,"number":71,"answer":"A","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Organização coletiva amplia a voz dos moradores","steps":["O texto aponta baixa representação dos grupos menos favorecidos.","Associações podem formular demandas e participar do planejamento.","E oferece um mecanismo direto de representação local."],"alternatives":{"A":"Reduzir impostos não cria por si um canal de participação.","B":"Privatizar espaços não garante representação dos moradores.","C":"Concentrar comércio não amplia necessariamente a voz popular.","D":"Condomínios fechados não equivalem à participação inclusiva.","E":"Associações de bairro organizam interesses e ampliam capacidade de reivindicação."},"takeaway":"Participação exige canais e condições efetivas de representação, não apenas previsão em lei.","key":"humanas:H398","area":"humanas","year":2021,"number":72,"answer":"E","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A morte de Vargas altera a reação das ruas","steps":["O suicídio ocorre numa crise com pressão pela saída do presidente.","A comoção desperta manifestações e hostilidade a opositores.","A é a reação imediata; não confunda 1954 com a queda de 1945 ou o golpe de 1964."],"alternatives":{"A":"A mobilização popular mudou o ambiente político contra seus adversários.","B":"Não houve implantação imediata de regime militar em agosto de 1954.","C":"O país já vivia ordem constitucional; não é esse o efeito imediato.","D":"Anticomunismo não é a repercussão central destacada.","E":"Os opositores foram pressionados pela reação, não simplesmente fortalecidos."},"takeaway":"Separe conjuntura imediata e acontecimentos de décadas diferentes.","key":"humanas:H107","area":"humanas","year":2021,"number":73,"answer":"A","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Proibir a língua procura apagar uma identidade","steps":["A ordem combina banimento e proibição do ensino aos filhos.","Impedir transmissão linguística atinge a continuidade cultural do grupo.","B identifica repressão a formas divergentes de interação social."],"alternatives":{"A":"O trecho não exige conversão religiosa como medida principal.","B":"A proibição busca suprimir um modo próprio de comunicação e pertença.","C":"Não se trata de impedir participação estrangeira no comércio.","D":"Não se apresenta envolvimento dos ciganos em revoltas nativistas.","E":"O alvo é a língua de um grupo deportado, não arte de povos autóctones."},"takeaway":"Língua é vínculo coletivo; impedir sua transmissão pode ser política de assimilação coercitiva.","key":"humanas:H004","area":"humanas","year":2021,"number":74,"answer":"B","subject":"História do Brasil","topic":"Brasil Colônia e povos indígenas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A medicina híbrida combina conhecimentos","steps":["A prática reúne medicina europeia e terapêutica indígena.","A experiência cotidiana amplia o repertório de quem atua.","E identifica conjugação de saberes empíricos, não substituição integral de um pelo outro."],"alternatives":{"A":"O uso de plantas não equivale necessariamente a ritual místico.","B":"Os jesuítas não abandonam os dogmas cristãos no relato.","C":"A tradição indígena é incorporada, não simplesmente superada.","D":"Não há imposição exclusiva da farmacologia nativa.","E":"Conhecimentos de origens diferentes são articulados na prática de cura."},"takeaway":"Hibridização envolve seleção e combinação, não ausência de relações coloniais de poder.","key":"humanas:H005","area":"humanas","year":2021,"number":75,"answer":"E","subject":"História do Brasil","topic":"Brasil Colônia e povos indígenas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A crítica e a língua acessível aproximam demandas religiosas","steps":["Francisco usa língua vulgar para alcançar mais ouvintes.","A preocupação com a distância entre Igreja e população também aparece em movimentos heréticos.","B identifica afinidade de demandas, não classifica Francisco como herege."],"alternatives":{"A":"Senhores feudais não são o grupo religioso crítico solicitado.","B":"Movimentos heréticos também questionavam práticas e privilégios eclesiásticos.","C":"Cruzadas são expedições político-religiosas, não a afinidade central.","D":"Corporações de ofício organizam trabalho urbano, não esse questionamento religioso.","E":"Universidades não são a categoria que resume a contestação indicada."},"takeaway":"Compartilhar uma preocupação não significa ter o mesmo estatuto institucional ou doutrina.","key":"humanas:H173","area":"humanas","year":2021,"number":76,"answer":"B","subject":"História Geral","topic":"Idade Média","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O debate compara a importância das universidades","steps":["Carvalho associa coesão à formação burocrática sem universidades coloniais.","Rueda relativiza esse papel e valoriza a circulação de impressos.","A localiza a divergência no peso das instituições de ensino na formação das identidades."],"alternatives":{"A":"Um autor atribui maior peso à formação institucional; o outro privilegia os impressos.","B":"Não se afirma que grupos de imprensa centralizaram a administração.","C":"Não há discussão de abandono de professores pelo poder público.","D":"Associações estudantis não são as instituições comparadas.","E":"O protagonismo da imprensa é a tese de um autor, não uma oposição explicitada por ambos nesse recorte."},"takeaway":"Em comparação historiográfica, identifique qual variável tem pesos explicativos diferentes.","key":"humanas:H006","area":"humanas","year":2021,"number":77,"answer":"A","subject":"História do Brasil","topic":"Brasil Colônia e povos indígenas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A revolução reúne sujeitos e reivindicações diversas","steps":["O primeiro texto privilegia liberdade contra tirania real.","O segundo enumera camponeses, tecelões e crentes com motivos distintos.","A identifica pluralidade de demandas, não uma causa única."],"alternatives":{"A":"Cercamentos, miséria e religião aparecem como reivindicações diferentes.","B":"Os grupos não formulam uma única demanda religiosa.","C":"A comparação evidencia abordagens históricas diferentes.","D":"As demandas têm profundidade social, não são descartadas como superficiais.","E":"A enumeração não estabelece supremacia exclusiva da economia."},"takeaway":"Uma revolução pode articular projetos distintos sem tornar todos os participantes ideologicamente iguais.","key":"humanas:H215","area":"humanas","year":2021,"number":78,"answer":"A","subject":"História Geral","topic":"Iluminismo e revoluções burguesas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O enclave se conecta mais ao exterior que ao entorno","steps":["O conceito exige poucos vínculos com a região imediata.","Trazer trabalhadores qualificados de fora reduz a integração com o mercado laboral local.","E exemplifica esse padrão, sem afirmar inexistência absoluta de empregos locais."],"alternatives":{"A":"Vilas operárias tendem a criar vínculos com o entorno da fábrica.","B":"Eventos comunitários ampliam relações locais, o contrário do traço destacado.","C":"Recuperação ambiental local não exemplifica a baixa articulação mencionada.","D":"Incorporar conhecimentos locais também fortaleceria vínculos com o território.","E":"Recrutar qualificação externamente exemplifica conexões extralocais e integração local limitada."},"takeaway":"Enclave não é isolamento total: pode ter fortes redes externas e fracos vínculos próximos.","key":"humanas:H399","area":"humanas","year":2021,"number":79,"answer":"E","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Velho e novo coexistem sem transição sincronizada","steps":["O autor descreve estruturas tradicionais em declínio e modernas em expansão.","Essa convivência produz ambivalência e adiamento político.","C sintetiza descompassos na construção institucional, não incapacidade natural do país."],"alternatives":{"A":"O texto não caracteriza as elites como radicalmente reformadoras.","B":"Não se restringe a erros de planos econômicos ortodoxos.","C":"Instituições e relações sociais mudam em ritmos desiguais e geram tensão.","D":"Não se declara ilegítima a representação de classes.","E":"Programas partidários são um recorte estreito para o processo estrutural analisado."},"takeaway":"Leia teorias de desenvolvimento em seu contexto histórico, sem convertê-las em destino inevitável.","key":"humanas:H831","area":"humanas","year":2021,"number":80,"answer":"C","subject":"Sociologia","topic":"Pensamento sociológico e método científico","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Oportunidades educacionais deveriam substituir privilégios","steps":["O manifesto propõe recrutar capacidades em todos os grupos.","A hierarquia democrática pretendida depende de oportunidades educacionais abertas.","B relaciona acesso à escola e valorização do mérito no projeto, não prova igualdade já realizada."],"alternatives":{"A":"O foco não é limitar formação às demandas técnicas do mercado.","B":"Abrir educação a todos permitiria reconhecer capacidades além da origem social.","C":"A finalidade não é apenas produzir administradores escolares.","D":"Pesquisa avançada e seu financiamento não são a relação central.","E":"Não se estabelece no trecho relação entre remuneração e fim do analfabetismo."},"takeaway":"Diferencie a promessa meritocrática de um projeto das condições históricas de sua realização.","key":"humanas:H108","area":"humanas","year":2021,"number":81,"answer":"B","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Perguntas examinam o conceito antes dos atributos","steps":["Sócrates distingue saber o que algo é de listar suas qualidades.","A pergunta sobre virtude exige examinar e formular uma definição.","B reconhece o método dialético da investigação por diálogo."],"alternatives":{"A":"O texto é diálogo, não carta dirigida a ausente.","B":"Perguntas e exame de respostas conduzem a busca de definição.","C":"Não se constrói uma cena de conflito trágico.","D":"A virtude não é reduzida a um mecanismo físico.","E":"Não se suspende simplesmente o julgamento; busca-se investigar o conceito."},"takeaway":"O questionamento socrático exige justificar definições, não apenas repetir exemplos.","key":"humanas:H648","area":"humanas","year":2021,"number":82,"answer":"B","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os objetos ensinam normas de convivência","steps":["Os signos codificam orientações sobre casamento e sensatez.","Os mais velhos os oferecem aos filhos para transmitir conhecimentos.","A define uma pedagogia de costumes sociais."],"alternatives":{"A":"As tampas e inscrições transmitem orientações e aprendizagem social.","B":"A função principal é ensinar, não impor um único meio de comunicação.","C":"Orientar jovens não implica desvalorizar todos os seus comportamentos.","D":"As mensagens procuram orientar o casamento, não destituir seu valor.","E":"O conteúdo não se restringe a registrar celebrações religiosas."},"takeaway":"Escrita e transmissão de saber podem usar suportes e códigos diferentes do alfabeto.","key":"humanas:H796","area":"humanas","year":2021,"number":83,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Celebrar juntos fortalece relações","steps":["Parentes e conhecidos se reúnem no tempo do caju.","A bebida e a brincadeira criam uma experiência compartilhada.","B identifica coesão social, sem reduzir o ritual a espetáculo externo."],"alternatives":{"A":"A festa não celebra uma narrativa oficial do Estado.","B":"O encontro reforça pertencimento e vínculos comunitários.","C":"Não se propõe eliminar a produção artesanal.","D":"O sentido é coletivo, não manipulação isolada da memória individual.","E":"Não há programa de modernização das trocas comerciais."},"takeaway":"Uma prática cultural pode reproduzir vínculos sociais por seu próprio modo de participação.","key":"humanas:H797","area":"humanas","year":2021,"number":84,"answer":"B","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Trabalhar como livre é estratégia de resistência","steps":["O anúncio registra fuga e apresentação de José como forro.","Ele se contrata como camarada em outra fazenda.","A identifica criação de relações de trabalho para sustentar uma vida fora do cativeiro."],"alternatives":{"A":"A contratação como camarada materializa uma inserção laboral alternativa ao cativeiro.","B":"O anúncio não descreve fundação de quilombo.","C":"As ameaças legais mostram repressão, não suavização das normas.","D":"Não se registra reconhecimento jurídico formal da liberdade ou do contrato.","E":"A atividade narrada é contratação em fazenda, não produção autônoma de subsistência."},"takeaway":"Uma fonte repressiva pode revelar iniciativas e estratégias de quem resistia à escravidão.","key":"humanas:H041","area":"humanas","year":2021,"number":85,"answer":"A","subject":"História do Brasil","topic":"Escravidão, abolição e resistências","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma árvore liga as ciências por fundamentos comuns","steps":["Metafísica é raiz, física é tronco e outras ciências são ramos.","A alegoria destaca dependência e articulação entre campos.","A identifica unidade essencial do conhecimento, sem dizer que os ramos sejam idênticos."],"alternatives":{"A":"Raízes, tronco e ramos representam um sistema conectado de saberes.","B":"O trecho não refuta especificamente uma crença fundamental.","C":"Especulação é um aspecto possível, mas não explica a arquitetura da metáfora.","D":"O método experimental não é apresentado como único fundamento.","E":"Não se propõe suspender todos os juízos nesse fragmento."},"takeaway":"Diferencie a questão específica da metáfora de outros conceitos conhecidos do mesmo filósofo.","key":"humanas:H667","area":"humanas","year":2021,"number":86,"answer":"A","subject":"Filosofia","topic":"Filosofia moderna: razão, ciência e conhecimento","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Amar esta vida contrasta com transferir sua realização ao além","steps":["Amor fati significa afirmar a existência, inclusive o inevitável.","A crítica se dirige à desvalorização desta vida em favor de uma realização transcendente.","E capta esse contraste, não uma afirmação de que todo cristão recuse afeto ou ciência."],"alternatives":{"A":"O trecho não critica apenas uma proibição de práticas afetivas.","B":"Não é uma discussão específica sobre obstáculo ao avanço científico.","C":"Não se centra na avaliação cristã de cultos pagãos.","D":"O alvo não é a condenação de toda filosofia antiga.","E":"Privilegiar uma realização fora deste mundo contrasta com afirmar a existência imanente."},"takeaway":"Em Nietzsche, situe a oposição entre afirmação da vida e sua subordinação a um além idealizado.","key":"humanas:H706","area":"humanas","year":2021,"number":87,"answer":"E","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A disciplina do corpo subordina o sensível ao espírito","steps":["O texto ordena conter desejos e suportar incômodos.","A carne deve ser castigada e sujeitada ao espírito.","E identifica desvalorização da materialidade corpórea nessa forma de ascetismo."],"alternatives":{"A":"Não se descrevem principalmente ritos e cerimônias litúrgicas.","B":"A justificativa é espiritual, não a autonomia da razão científica.","C":"Trabalho é recomendado para a sujeição da carne, não simplesmente desqualificado.","D":"Não há classificação específica de alimentos puros e impuros.","E":"Prazeres e demandas corporais são subordinados à finalidade espiritual."},"takeaway":"Ascetismo envolve práticas de renúncia e disciplina; observe qual dimensão é subordinada.","key":"humanas:H174","area":"humanas","year":2021,"number":88,"answer":"E","subject":"História Geral","topic":"Idade Média","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A sombra aponta no sentido oposto ao Sol","steps":["Em junho, a maior incidência solar se desloca ao hemisfério norte.","Brasília está ao sul do Equador; no meio-dia do modelo, o Sol fica ao norte.","A sombra se projeta ao sul: B. Horário civil e meio-dia solar exato são idealizados no item."],"alternatives":{"A":"Norte é a direção do Sol, e não da sombra nesse horário.","B":"Ao estar o Sol ao norte, a sombra do prédio aponta para o sul.","C":"Leste é orientação associada ao nascer do Sol, não ao meio-dia considerado.","D":"Oeste corresponderia a sombra matinal, não à situação do comando.","E":"Nordeste tampouco se opõe à direção norte do Sol no modelo."},"takeaway":"Sombra e posição aparente do Sol têm sentidos opostos; leve em conta latitude e estação.","key":"humanas:H560","area":"humanas","year":2021,"number":89,"answer":"B","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A limpeza revela a hierarquia escravista","steps":["A imagem mostra carregadores de dejetos.","O texto diz que a tarefa era destinada a escravizados de menor status.","B identifica reiteração de hierarquias sociais por distribuição desigual do trabalho."],"alternatives":{"A":"A tarefa é desvalorizada e imposta a grupos subordinados.","B":"O serviço urbano reproduz posições desiguais de poder e status.","C":"Não se atribui caráter sagrado à tarefa de transportar resíduos.","D":"A atividade reforça exclusão, não a supera.","E":"O argumento não envolve mudança de uma tradição religiosa."},"takeaway":"Atribuir tarefas e riscos a determinados grupos pode reproduzir a ordem social.","key":"humanas:H271","area":"humanas","year":2021,"number":90,"answer":"B","subject":"Geografia","topic":"Meio ambiente e problemas ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
